from fastapi.openapi.models import SecurityBase as SecurityBaseModel


class SecurityBase:
    model: SecurityBaseModel
    scheme_name: str

    def get_all_scopes(self) -> set[str]:
        """
        Returns a set of all scopes required by this security scheme.
        This method is intended to support hierarchical scope propagation.
        """
        return set()

@dataclass
class SecurityRequirement:
    security_scheme: SecurityBase
    scopes: Optional[Sequence[str]] = None

    def __post_init__(self):
        if self.scopes is None:
            self.scopes = list(self.security_scheme.get_all_scopes())

